const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['techstack', 'cmsdetect'], 'Network Tools', 'Guess what a website is built with', async ({ sock, from, msg, args }) => {
  const url = args[0];
  if (!url) return sock.sendMessage(from, { text: 'Usage: .techstack https://example.com' }, { quoted: msg });
  try {
    const res = await fetch(url);
    const html = await res.text();
    const generator = html.match(/<meta name="generator" content="([^"]+)"/i)?.[1];
    const hints = [];
    if (/wp-content/i.test(html)) hints.push('WordPress');
    if (/cdn\.shopify/i.test(html)) hints.push('Shopify');
    if (/_next\//i.test(html)) hints.push('Next.js');
    await sock.sendMessage(from, { text: `🧩 *Tech guess for ${url}*\n${generator ? 'Generator: ' + generator + '\n' : ''}${hints.length ? hints.join(', ') : 'No strong signals found.'}` }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Could not analyze that site.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
